'use strict';

class CsvError extends Error {
  constructor(message, line, column) {
    super(`${message} (line ${line}, column ${column})`);
    this.name = 'CsvError';
    this.line = line;
    this.column = column;
  }
}

function checkDelimiter(d) {
  if (d === undefined) return ',';
  if (typeof d !== 'string' || d.length !== 1 || d === '"' || d === '\r' || d === '\n') {
    throw new TypeError('delimiter must be a single character other than ", CR or LF');
  }
  return d;
}

function setKey(obj, key, value) {
  Object.defineProperty(obj, key, { value, enumerable: true, writable: true, configurable: true });
}

function parse(text, options = {}) {
  if (typeof text !== 'string') throw new TypeError('text must be a string');
  if (options === null || typeof options !== 'object') throw new TypeError('options must be an object');
  const delim = checkDelimiter(options.delimiter);
  const useHeader = options.header === true;
  const skipEmpty = options.skipEmptyLines === true;

  const n = text.length;
  let i = text.charCodeAt(0) === 0xfeff ? 1 : 0;

  const posOf = (idx) => {
    let line = 1;
    let lineStart = 0;
    for (let k = 0; k < idx; k++) {
      const c = text[k];
      if (c === '\n' || (c === '\r' && text[k + 1] !== '\n')) {
        line++;
        lineStart = k + 1;
      }
    }
    return [line, idx - lineStart + 1];
  };
  const fail = (msg, idx) => {
    const [l, c] = posOf(idx);
    throw new CsvError(msg, l, c);
  };

  const out = [];
  let header = null;
  let headerIndex = null;

  while (i < n) {
    const recStart = i;
    const fields = [];
    const starts = [];
    let emptyLine = false;
    for (;;) {
      starts.push(i);
      if (text[i] === '"') {
        const open = i;
        let j = i + 1;
        let val = '';
        for (;;) {
          const q = text.indexOf('"', j);
          if (q === -1) fail('Unclosed quoted field', open);
          val += text.slice(j, q);
          if (text[q + 1] === '"') {
            val += '"';
            j = q + 2;
          } else {
            j = q + 1;
            break;
          }
        }
        if (j < n && text[j] !== delim && text[j] !== '\r' && text[j] !== '\n') {
          fail('Unexpected character after closing quote', j);
        }
        fields.push(val);
        i = j;
      } else {
        let j = i;
        while (j < n && text[j] !== delim && text[j] !== '\r' && text[j] !== '\n') j++;
        fields.push(text.slice(i, j));
        if (j === i && fields.length === 1) emptyLine = true;
        i = j;
      }
      if (i < n && text[i] === delim) {
        i++;
        emptyLine = false;
        continue;
      }
      break;
    }
    if (i < n) {
      if (text[i] === '\r' && text[i + 1] === '\n') i += 2;
      else i++;
    }
    if (emptyLine && fields.length === 1 && skipEmpty) continue;

    if (!useHeader) {
      out.push(fields);
    } else if (!header) {
      headerIndex = new Set();
      fields.forEach((name, k) => {
        if (headerIndex.has(name)) fail('Duplicate header name', starts[k]);
        headerIndex.add(name);
      });
      header = fields;
    } else {
      if (fields.length !== header.length) fail('Wrong number of fields', recStart);
      const obj = {};
      header.forEach((name, k) => setKey(obj, name, fields[k]));
      out.push(obj);
    }
  }
  return out;
}

function stringify(rows, options = {}) {
  if (!Array.isArray(rows)) throw new TypeError('rows must be an array');
  if (options === null || typeof options !== 'object') throw new TypeError('options must be an object');
  const delim = checkDelimiter(options.delimiter);
  const eol = options.eol === undefined ? '\r\n' : options.eol;
  if (eol !== '\r\n' && eol !== '\n') throw new TypeError("eol must be '\\r\\n' or '\\n'");
  const header = options.header;
  if (header !== undefined && !Array.isArray(header)) throw new TypeError('header must be an array');

  let first = true;
  const field = (v) => {
    let s;
    if (typeof v === 'string') s = v;
    else if (typeof v === 'number' || typeof v === 'boolean') s = String(v);
    else if (v === null || v === undefined) s = '';
    else throw new TypeError('unsupported value type: ' + typeof v);
    const bom = first && s.charCodeAt(0) === 0xfeff;
    first = false;
    if (
      bom || s.includes(delim) || s.includes('"') || s.includes('\r') || s.includes('\n') ||
      s.startsWith(' ') || s.endsWith(' ')
    ) {
      return '"' + s.replace(/"/g, '""') + '"';
    }
    return s;
  };
  const line = (values) => {
    if (values.length === 1 && values[0] === '') {
      first = false;
      return '""';
    }
    return values.map(field).join(delim);
  };

  let res = '';
  if (header) res += line(header) + eol;
  for (const row of rows) {
    let values;
    if (Array.isArray(row)) values = row;
    else if (header && row !== null && typeof row === 'object') {
      values = header.map((h) => (Object.prototype.hasOwnProperty.call(row, h) ? row[h] : undefined));
    } else throw new TypeError('each row must be an array' + (header ? ' or object' : ''));
    res += line(values) + eol;
  }
  return res;
}

module.exports = { parse, stringify, CsvError };
